contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 mAssetAmount, address to) public payable {
        require(to != address(0), "beneficiary zero");
        require(msg.sender != address(0), "sender zero");

        // Setup: give the caller some credits by supplying mAsset.
        // The test contract must hold some mAsset; since this test has no mAsset,
        // use a small bootstrap: supply 0 is not allowed by IYieldSource, so require a deposit first.
        // To keep it self-contained without external calls, we attempt a direct redeem with the caller's existing credits.
        // Read before-values
        uint256 creditsBeforeCaller = c.imBalances(msg.sender);
        uint256 creditsBeforeThis = c.imBalances(address(this));
        uint256 exchangeRateBefore = c.balanceOfToken(address(this)) == 0 && creditsBeforeThis == 0 ? 1e18 : 0; // placeholder not used

        // Read the actual exchange rate indirectly via balanceOfToken with a known credit amount?
        // balanceOfToken(addr) = imBalances[addr] * exchangeRate / 1e18.
        // If imBalances[addr] is 0, result is 0. To get exchange rate, we need a nonzero balance.
        // Instead, read the public savings contract exchangeRate directly (savings is public immutable).
        uint256 exchangeRate = c.savings().exchangeRate();

        uint256 mAssetBalanceBefore = IERC20(c.depositToken()).balanceOf(address(c));

        // The deciding call: top-level statement.
        uint256 returnedActual;
        bool reverted;
        try c.redeemToken(mAssetAmount) returns (uint256 actual) {
            returnedActual = actual;
            reverted = false;
        } catch {
            returnedActual = 0;
            reverted = true;
        }

        // After-values
        uint256 creditsAfterCaller = c.imBalances(msg.sender);
        uint256 creditsAfterThis = c.imBalances(address(this));
        uint256 mAssetBalanceAfter = IERC20(c.depositToken()).balanceOf(address(c));

        // General rule:
        // 1) The caller's credit balance (imBalances[msg.sender]) cannot increase.
        //    In this contract, credits are only added via supplyTokenTo(to) and subtracted in redeemToken.
        //    redeemToken can only decrease credits of msg.sender (or revert).
        // 2) The amount returned (mAssetsActual) is at most the decrease in the contract's mAsset balance.
        //    Because mAssetsActual = mAssetBalanceAfter - mAssetBalanceBefore (when the savings.redeemUnderlying succeeds).
        //    However, due to possible external transfers in the savings contract, we assert a weaker but meaningful bound:
        //    the returned amount is at most the decrease in the contract's mAsset balance.
        // 3) If reverted, credits of caller must not change and returnedActual == 0.
        // The rule below combines these per focus: "the value returned by a call redeemToken(args) that completes".
        // We assert for the completed case: returnedActual <= (mAssetBalanceBefore - mAssetBalanceAfter) and creditsAfterCaller <= creditsBeforeCaller.
        // But subtraction may underflow if mAssetBalanceAfter > mAssetBalanceBefore; that should not happen but handle safely:
        bool noCreditIncrease = creditsAfterCaller <= creditsBeforeCaller;
        bool returnBound = mAssetBalanceBefore >= mAssetBalanceAfter
            ? returnedActual <= (mAssetBalanceBefore - mAssetBalanceAfter)
            : false; // if balance increased, something is wrong

        assert(
            reverted
                ? (returnedActual == 0 && creditsAfterCaller == creditsBeforeCaller)
                : (noCreditIncrease && returnBound)
        );
    }

    receive() external payable {}
}

