contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address to) public payable {
        require(to != address(0), "recipient must not be zero");
        require(address(this).balance >= amount, "insufficient ether for transfer");

        address mAssetAddr = c.depositToken();
        require(mAssetAddr != address(0), "no deposit token");

        uint256 balBeforeDeposit = IERC20(mAssetAddr).balanceOf(address(this));

        // The test contract needs tokens to deposit into c. Since c gets tokens
        // from msg.sender via safeTransferFrom, there must be an allowance and
        // balance already in place; the setup is done in the test harness.
        // We only read pre-state here.
        uint256 imBefore = c.imBalances(to);

        c.supplyTokenTo(amount, to);

        uint256 imAfter = c.imBalances(to);

        // The credits issued by the savings contract for the deposited amount.
        // We can obtain this from the savings contract directly, but c exposes
        // only through public getters; savings is a public immutable on c.
        // However, reading c.savings() is allowed via the auto-generated getter.
        // Compute the expected credits via savings.underlyingToCredits(amount)
        // (a view function on the savings contract).
        ISavingsContractV2 savings = c.savings();
        uint256 expectedCredits = savings.underlyingToCredits(amount);

        // The pre-existing imBalances(to) is overwritten by the internal accounting
        // in c; supplyTokenTo does: creditsIssued = savings.depositSavings(mAssetAmount);
        // imBalances[to] += creditsIssued; so the delta must equal the credits issued
        // for that amount (assuming no prior balance). In general, if there was a
        // prior balance, the delta is still the credits issued.
        // We assert the general rule: imBalances increases by exactly the credits
        // issued for the deposited amount, regardless of the recipient.
        // However, the test contract cannot compute creditsIssued directly without
        // calling depositSavings (which would be a state-changing call on savings,
        // not allowed in assert). Instead, we use the invariant that underlyingToCredits
        // is used by the savings contract to mint credits, and depositSavings returns
        // creditsIssued. Since underlyingToCredits is a view, we can compare.
        // Note: In some savings contracts, depositSavings returns the amount of
        // credits issued, which should match underlyingToCredits(amount) if the
        // exchange rate is the same before and after. This is a reasonable general
        // rule for the tested contract C.
        // The caller's own imBalances is not affected unless to == msg.sender.
        // The test contract's token balance may change, but we focus on imBalances.

        // To make the rule robust, we assert that the new balance is at least
        // the old balance plus 0, and that the increase is at most the maximum
        // possible credits. But the general rule is: imAfter == imBefore + credits.
        // We can read credits by observing the savings contract's total credits?
        // No. Instead, we assert that the balance increase is positive when amount>0
        // and that it is exactly the credits that would be minted for the amount.
        // Since we cannot call depositSavings again (it would alter state), we assume
        // that underlyingToCredits is the correct conversion and that depositSavings
        // uses the same logic. This is a property of the savings contract, but for
        // the purpose of this test, we assert that imBalances(to) increased by
        // exactly the amount of credits that the savings contract reports for the
        // deposited amount via underlyingToCredits.

        assert(imAfter == imBefore + expectedCredits);
    }

    receive() external payable {}
}

