        } else {
            assert(
                got == cBalBefore - cBalAfter &&
                cBalBefore > cBalAfter &&
                creditsBefore > creditsAfter &&
                (creditsBefore - creditsAfter) * exchangeRateBefore <= got * 1e18 &&
                exchangeRateAfter == exchangeRateBefore
            );
        }
