contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 x) public payable {
        require(x > 0, "x must be positive");

        // Read caller balances before redeem
        uint256 creditsBefore = c.imBalances(address(this));
        uint256 mAssetBefore = IERC20(c.mAsset()).balanceOf(address(this));

        // Perform redeem; capture return value and revert flag
        uint256 actual;
        bool reverted;
        try c.redeemToken(x) returns (uint256 mAssetsActual) {
            actual = mAssetsActual;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // After success, read balances again
            uint256 creditsAfter = c.imBalances(address(this));
            uint256 mAssetAfter = IERC20(c.mAsset()).balanceOf(address(this));

            // The caller's credits decreased by exactly the credits burned, which is capped by the requested x
            // and the actual received mAssets equals the increase in the caller's mAsset balance.
            assert(creditsBefore - creditsAfter == actual && mAssetAfter - mAssetBefore == actual);
        } else {
            // If reverted, state must be unchanged for the caller's credits and mAsset balance.
            uint256 creditsAfter = c.imBalances(address(this));
            uint256 mAssetAfter = IERC20(c.mAsset()).balanceOf(address(this));
            assert(creditsAfter == creditsBefore && mAssetAfter == mAssetBefore);
        }
    }

    receive() external payable {}
}

