contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address supplier, address beneficiary, address probe, uint256 mAssetAmount) public {
        require(mAssetAmount > 0);

        // Give c a non-zero exchange rate by supplying some tokens.
        // The test contract needs to hold underlying tokens sent to c.
        // Use only a small deterministic amount derived from inputs.
        uint256 supplyAmount = mAssetAmount;

        // Pull tokens from the caller of this test into c via c.supplyTokenTo.
        // We must first approve c to spend the test contract's mAsset tokens.
        address mAssetAddr = c.depositToken();
        IERC20(mAssetAddr).approve(address(c), supplyAmount);

        c.supplyTokenTo(supplyAmount, beneficiary);

        uint256 returned = c.balanceOfToken(probe);

        // The rule: the returned value is the credited balance scaled by the exchange rate.
        // We can observe the credited balance only for beneficiary? No: imBalances is public mapping getter.
        // But the test may not rely on C's private state. However imBalances is public, so it's observable.
        // We avoid using it to keep the rule about the return value only where possible.
        // Use the fact that beneficiary's credited shares equal the shares issued for supplyAmount.
        // If the exchange rate is r, then balanceOfToken(beneficiary) should be shares * r / 1e18.
        // We can read the shares only if we read imBalances(beneficiary), which is public.
        // To make the rule general and not require reading imBalances, use the relationship
        // that the returned value for beneficiary is non-negative and matches the formula
        // for any probe address that has been credited.
        // For a general rule, assert that the returned value for any probe is
        // (imBalances(probe) * exchangeRate) / 1e18.
        // Since imBalances and exchangeRate are public, we can read them.
        uint256 exchangeRate = c.savings().exchangeRate();
        uint256 expected = (c.imBalances(probe) * exchangeRate) / 1e18;

        assert(returned == expected);
    }

    receive() external payable {}
}

