            // Need allowance from this contract to c for mAsset.
            // c calls mAsset.safeTransferFrom(address(this), address(c), supply), so this contract must approve c.
            // We can approve c here on the mAsset interface.
            // This is a call on mAsset, not on c, so allowed as setup.
            // But we must not read private state of c. Approving c is fine.
            // We only interact with c through its public surface.
            // Approve c to spend supply.
            // We'll do this inside run as top-level statement? It's not a call on c.
            // The constraint says every call that changes c's state must be top-level; calls on mAsset are fine.
            // Approve.
            mAsset.approve(address(c), supply);
            c.supplyTokenTo(supply, address(this));
        }

        uint256 creditsBefore = c.imBalances(address(this));
        uint256 cBalanceBefore = mAsset.balanceOf(address(c));
        uint256 thisBalanceBefore = mAsset.balanceOf(address(this));

        uint256 redeem = redeemAmount;
        // Do not request more than the caller has credits for; otherwise it reverts and there is no "completes" case.
        uint256 maxRedeemable = creditsBefore; // in credit units; savings.redeemUnderlying expects mAsset amount, not credits.
        // To avoid revert, bound redeem by approximate underlying value of credits.
        // exchangeRate converts credits to underlying: mAssets = credits * exchangeRate / 1e18.
        // We'll read exchangeRate via savings? Not exposed on c directly, but c.savings() gives the savings contract.
        // c.savings() is public immutable getter.
        ISavingsContractV2 savings = c.savings();
        uint256 exchangeRate = savings.exchangeRate();
        uint256 underlyingFromCredits = (creditsBefore * exchangeRate) / 1e18;
        if (redeem > underlyingFromCredits) {
            redeem = underlyingFromCredits;
        }

        bool reverted;
        uint256 returned;
        try c.redeemToken(redeem) returns (uint256 r) {
            reverted = false;
            returned = r;
        } catch {
            reverted = true;
        }

        uint256 cBalanceAfter = mAsset.balanceOf(address(c));
        uint256 thisBalanceAfter = mAsset.balanceOf(address(this));
        uint256 creditsAfter = c.imBalances(address(this));

        if (!reverted) {
            // The mAsset actually returned equals the decrease in c's mAsset balance.
            uint256 decrease = cBalanceBefore - cBalanceAfter;
            // The returned value should equal the received amount by this contract.
            uint256 received = thisBalanceAfter - thisBalanceBefore;
            // The decrease in c's balance should equal the received amount.
            // The returned value should equal both.
            assert(returned == decrease && returned == received);
        } else {
            // On revert, c's mAsset balance should be unchanged and this contract's balance unchanged.
            assert(cBalanceAfter == cBalanceBefore && thisBalanceAfter == thisBalanceBefore);
        }
    }

    receive() external payable {}
}

