    function run(uint256 redeemAmount) public {
        // Precondition: the test contract must hold credits so a redeem can succeed.
        // The test contract is funded with mAsset and credits by prior setup; here we just
        // read the public surface and perform the deciding call.
        IERC20 mAsset = IERC20(c.depositToken());
        ISavingsContractV2 savings = c.savings();

        uint256 creditsBefore = c.imBalances(address(this));
        uint256 cBalanceBefore = mAsset.balanceOf(address(c));
        uint256 thisBalanceBefore = mAsset.balanceOf(address(this));

