        // Bound the requested redeem to the underlying value of the caller's credits.
        uint256 maxRedeemable = (creditsBefore * exchangeRate) / 1e18;
        uint256 redeem = redeemAmount % (maxRedeemable + 1);

        bool reverted;
        uint256 returned;
        try c.redeemToken(redeem) returns (uint256 r) {
