contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 depositAmount, uint256 redeemAmount) public {
        // ensure the caller has some credits to redeem
        c.supplyTokenTo(depositAmount, address(this));

        uint256 creditsBefore = c.imBalances(address(this));
        uint256 mAssetBefore = IERC20(c.mAsset()).balanceOf(address(this));

        bool reverted;
        try c.redeemToken(redeemAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 creditsAfter = c.imBalances(address(this));
        uint256 mAssetAfter = IERC20(c.mAsset()).balanceOf(address(this));

        if (!reverted) {
            // credits must have decreased by the amount actually burned
            assert(creditsBefore >= creditsAfter);
            // the amount of mAsset received must equal the decrease in credits modulo exchange rate scaling
            // exchangeRate is 1e18-scaled, so creditsBurned = (mAssetReceived * 1e18) / exchangeRate
            uint256 exchangeRate = c.savings().exchangeRate();
            if (exchangeRate > 0) {
                uint256 mAssetReceived = mAssetAfter - mAssetBefore;
                assert(mAssetReceived <= (creditsBefore - creditsAfter) * exchangeRate / 1e18 + 1);
            }
        } else {
            assert(creditsAfter == creditsBefore);
            assert(mAssetAfter == mAssetBefore);
        }
    }
}

