        c.supplyTokenTo(depositAmount, address(this));

        uint256 creditsBeforeCaller = c.imBalances(address(this));
        uint256 exchangeRateBefore = c.savings.exchangeRate();

        // Fund the test contract with more mAsset to allow the redeem to succeed.
        // (Redeem returns underlying to c, which then transfers to the caller.)
        if (IERC20(asset).balanceOf(address(this)) < redeemAmount) {
            // Cannot mint here; instead require that the balance is sufficient.
            require(IERC20(asset).balanceOf(address(this)) >= redeemAmount, "insufficient test balance for redeem");
        }
        require(IERC20(asset).balanceOf(address(this)) >= redeemAmount, "insufficient test balance for redeem");

        // Record the other account's credit balance before the redeem.
        uint256 otherCreditsBefore = c.imBalances(other);

        uint256 mAssetBalanceBefore = IERC20(asset).balanceOf(address(this));

        // Perform the redeem as the caller.
        bool reverted;
        uint256 mAssetsActual;
        try c.redeemToken(redeemAmount) returns (uint256 _mAssetsActual) {
            reverted = false;
            mAssetsActual = _mAssetsActual;
        } catch {
            reverted = true;
            mAssetsActual = 0;
        }

        // The general rule:
        // 1. On success, the caller's imBalances must decrease by creditsBurned.
        // 2. On success, any other account's imBalances must be unchanged.
        // 3. The actual mAssets returned must equal the mAsset balance increase of the test contract.
        uint256 creditsAfterCaller = c.imBalances(address(this));
        uint256 otherCreditsAfter = c.imBalances(other);

        // Compute credits burned from the exchange rate and actual amount returned.
        // creditsBurned = redeemAmount * 1e18 / exchangeRate (approximately, integer division).
        // The contract uses redeemUnderlying which returns credits burned; we cannot observe it directly,
        // but we can deduce it from the balance change of the test contract's mAsset and the caller's credits.
        // Instead, we assert the observable invariants:
        bool rule = true;
        if (!reverted) {
            // Caller's credit balance must have decreased (or stayed the same if zero credits burned).
            // It cannot increase.
            rule = rule && (creditsAfterCaller <= creditsBeforeCaller);
            // Other account's credit balance must be exactly unchanged.
            rule = rule && (otherCreditsAfter == otherCreditsBefore);
            // The test contract must have received exactly mAssetsActual mAsset tokens.
            // (Already implied by the return value, but check balance delta.)
            uint256 mAssetBalanceAfter = IERC20(asset).balanceOf(address(this));
            rule = rule && (mAssetBalanceAfter - mAssetBalanceBefore == mAssetsActual);
            // Also, the caller's credit decrease must be consistent with the amount redeemed:
            // creditsBurned * exchangeRate / 1e18 == mAssetsActual (up to rounding).
            // Since we cannot read the exact creditsBurned, we verify the reverse direction:
            // The creditsBurned implied by mAssetsActual must be <= credits decrease.
            uint256 creditsDecrease = creditsBeforeCaller - creditsAfterCaller;
            uint256 impliedCreditsBurned = (mAssetsActual * 1e18) / exchangeRateBefore;
            // Due to rounding, impliedCreditsBurned may be slightly less or more; assert it's within 1.
            // Use a tolerance to avoid false positives from rounding.
            if (impliedCreditsBurned > creditsDecrease) {
                rule = rule && (impliedCreditsBurned - creditsDecrease <= 1);
            } else {
                rule = rule && (creditsDecrease - impliedCreditsBurned <= 1);
            }
        } else {
            // On revert, no state changes should have occurred.
            rule = rule && (creditsAfterCaller == creditsBeforeCaller);
            rule = rule && (otherCreditsAfter == otherCreditsBefore);
        }

        assert(rule);
    }

    receive() external payable {}
}

