        // General rule:
        // - On success, any other account's imBalances is unchanged.
        // - On success, the caller's imBalances must not increase.
        // - On revert, no state changes occurred.
        bool rule;
        if (!reverted) {
            rule = (otherCreditsAfter == otherCreditsBefore) && (creditsAfterCaller <= creditsBeforeCaller);
        } else {
            rule = (otherCreditsAfter == otherCreditsBefore) && (creditsAfterCaller == creditsBeforeCaller);
        }

        assert(rule);
    }

    receive() external payable {}
}

