contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 supplyAmount, uint256 redeemAmount) public {
        // Ensure c has mAsset liquidity and the caller has credits before redeeming.
        // Donation is only useful if redeemAmount <= supplyAmount-derived credits.
        uint256 rateBefore = c.savings().exchangeRate();
        uint256 creditsBefore = rateBefore == 0 ? 0 : (redeemAmount * 1e18) / rateBefore;
        require(creditsBefore <= supplyAmount, "test precondition: enough supplied credits");

        // Supply mAsset to c and record the resulting credit balance for this test contract.
        c.supplyTokenTo(supplyAmount, address(this));
        uint256 imBalancesBefore = c.imBalances(address(this));

        // Decide whether the redeem is expected to fit within the credit balance.
        uint256 rateNow = c.savings().exchangeRate();
        uint256 creditsNeeded = rateNow == 0 ? 0 : (redeemAmount * 1e18) / rateNow;
        bool shouldFit = creditsNeeded <= imBalancesBefore;

        bool reverted;
        uint256 returned;
        try c.redeemToken(redeemAmount) returns (uint256 mAssetsActual) {
            returned = mAssetsActual;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (shouldFit) {
            uint256 imBalancesAfter = c.imBalances(address(this));
            assert(
                !reverted &&
                imBalancesAfter <= imBalancesBefore &&
                returned >= redeemAmount &&
                returned <= redeemAmount + 1e18
            );
        } else {
            assert(reverted);
        }
    }

    receive() external payable {}
}

