contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, address to, address other) public {
        require(to != other, "addresses must differ");

        // mAsset is a public immutable IERC20; read the deposit token through the public getter
        address token = c.depositToken();
        require(token != address(0), "no deposit token");

        // Precondition: this test contract must own enough mAsset to call supplyTokenTo.
        // We obtain mAsset by redeeming any existing balance from the yield source,
        // or by using the allowances the constructor set up. Since we cannot mint here,
        // restrict to the case where we already hold enough mAsset.
        // (IERC20 mAsset = c.mAsset(); address token = address(mAsset);)
        // To be safe, read the balance via the ERC20 surface.
        uint256 bal = IERC20Like(token).balanceOf(address(this));
        require(bal >= amount, "insufficient mAsset balance");

        uint256 beforeTo = c.balanceOfToken(to);
        uint256 beforeOther = c.balanceOfToken(other);

        bool reverted;
        try c.supplyTokenTo(amount, to) { reverted = false; } catch { reverted = true; }

        if (!reverted) {
            uint256 afterTo = c.balanceOfToken(to);
            uint256 afterOther = c.balanceOfToken(other);
            assert(afterTo >= beforeTo && afterOther == beforeOther);
        } else {
            // If the supply reverted, balances must not have increased
            uint256 afterTo = c.balanceOfToken(to);
            uint256 afterOther = c.balanceOfToken(other);
            assert(afterTo == beforeTo && afterOther == beforeOther);
        }
    }

    receive() external payable {}
}

// Minimal ERC20 surface used only inside the test; full IERC20 is already in the unit.
interface IERC20Like {
    function balanceOf(address account) external view returns (uint256);
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to) public {
        // balanceOfToken is a view call: it must complete for any address and its
        // return value must equal the cached credits balance of `to` scaled by the
        // exchange rate reported by the savings contract.
        // We read the rate via the public immutable `savings` getter and the
        // public imBalances mapping through c. The deciding call is balanceOfToken.

        uint256 exchangeRate = c.savings().exchangeRate();
        uint256 credits = c.imBalances(to);

        // This is the deciding call (view, read into a local).
        uint256 reported = c.balanceOfToken(to);

        assert(reported == (credits * exchangeRate) / 1e18);
    }

    receive() external payable {}
}

